tl.to("#dark", { opacity: 0.86, duration: 0.14, ease: "none" }, 43.6);
/* The pattern, flashed for real: 3 long, 3 short, 3 long.
   Each pulse is a fromTo at BOTH ends. A plain .to() records its start value on
   first render, and the renderer seeks frames out of order, so chained .to()
   tweens on one property silently flatten into no visible flash at all. */
(() => {
  const T = ["#sosL", "#sosR"], DIM = 0.10, LIT = 1;
  const pat = [[0.00,0.50],[0.72,0.50],[1.44,0.50],
               [2.34,0.16],[2.74,0.16],[3.14,0.16],
               [3.86,0.50],[4.58,0.50],[5.30,0.50]];
  pat.forEach(([o, len]) => {
    tl.fromTo(T, { opacity: DIM }, { opacity: LIT, duration: 0.05, ease: "none" }, 50.6 + o);
    tl.fromTo(T, { opacity: LIT }, { opacity: DIM, duration: 0.05, ease: "none" }, 50.6 + o + len);
  });
})();

